import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long m = Long.parseLong(next());
        String[] logs = new String[(int) m];
        for (int i = 0; i < logs.length; i++) logs[i] = next();

        long[] time = new long[(int) n];
        Deque<Integer> stack = new ArrayDeque<>();
        long prev = 0;
        for (int i = 0; i < m; i++) {
            String[] parts = logs[i].split(":");
            int fid = Integer.parseInt(parts[0]);
            long t = Long.parseLong(parts[2]);
            if (parts[1].equals("start")) {
                if (!stack.isEmpty()) time[stack.peek()] += t - prev;
                stack.push(fid);
                prev = t;
            } else {
                time[stack.pop()] += t - prev + 1;
                prev = t + 1;
            }
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) sb.append(time[i]).append(i + 1 < n ? " " : "\n");
        System.out.print(sb);
    }
}
